function initialize(bool _live, address _feeTo) public {
    require(!initialized, "contract is already initialized");
    AqueductDistributionLive = _live;
    feeTo = _feeTo;
    owner = msg.sender;
    emit LogSetOwner(msg.sender);
    feeBPS = 20;
    initialized = true;
    matchingEnabled = true;
    buyEnabled = true;
}

function buy(uint256 id, uint256 amount) public override can_buy(id) returns (bool) {
    require(!locked, "Reentrancy attempt");
    if (AqueductDistributionLive) {
        IAqueduct(AqueductAddress).distributeToMakerAndTaker( getOwner(id), msg.sender );
    }
    function(uint256, uint256) returns (bool) fn = matchingEnabled ? _buys : super.buy;
    return fn(id, amount);
}

function setFeeBPS(uint256 _newFeeBPS) external auth returns (bool) {
    feeBPS = _newFeeBPS;
    return true;
}
